#ifndef upstream_GBK_TABLE_H_
#define upstream_GBK_TABLE_H_

#include <cstddef>
#include <cstdint>
#include <string>

namespace upstream {

struct GbkEntry {
    uint16_t gbk;
    uint16_t uni;
};

struct UniEntry {
    uint16_t uni;
    uint16_t gbk;
};

/* Generated by gen_gbk_table.py (cp936). Sorted by first member. */
extern const GbkEntry kGbkToUni[];
extern const size_t kGbkToUniCount;
extern const UniEntry kUniToGbk[];
extern const size_t kUniToGbkCount;

/* Convert one GBK double-byte code to Unicode CP. 0 if unmapped. */
uint16_t GbkToUni(uint16_t gbk);

/* Convert one Unicode BMP CP to GBK code. 0 if unmapped. */
uint16_t UniToGbk(uint16_t uni);

/* Decode a GBK byte stream to UTF-8.
 * Incomplete lead byte at end is held back: returns bytes consumed, appends
 * converted UTF-8 to out. Invalid sequences are replaced with U+FFFD (EF BF BD). */
size_t GbkDecode(const char *in, size_t len, std::string &out);

/* Encode a UTF-8 string to GBK bytes. Unmappable characters become '?' (0x3F).
 * Returns false if the input contains malformed UTF-8 (output still best-effort). */
bool Utf8ToGbk(const std::string &in, std::string &out);

} // namespace upstream

#endif // upstream_GBK_TABLE_H_
